// Extract patient data from Typeform submission
const submission = $input.first().json;

// Hidden fields (from URL parameters)
const hidden = submission.hidden || {};

// Form answers (patient-entered data)
const answers = submission.answers || {};

// Extract data with fallbacks
const patientData = {
  // From hidden fields (tracking)
  appointmentId: hidden.appointment_id || '',
  appointmentDate: hidden.appointment_date || '',
  appointmentTime: hidden.appointment_time || '',
  phoneFromHidden: hidden.phone || '',

  // Demographics (from form)
  fullName: answers['Full Name'] || answers['full_name'] || hidden.patient_name || '',
  firstName: '',
  lastName: '',
  dateOfBirth: answers['Date of Birth'] || answers['date_of_birth'] || '',
  gender: answers['Gender'] || answers['gender'] || '',
  email: answers['Email'] || answers['email'] || '',
  phone: answers['Phone'] || answers['phone'] || hidden.phone || '',

  // Address
  streetAddress: answers['Street Address'] || answers['street_address'] || '',
  city: answers['City'] || answers['city'] || '',
  state: answers['State'] || answers['state'] || '',
  zipCode: answers['ZIP Code'] || answers['zip_code'] || '',

  // Insurance
  insuranceCompany: answers['Insurance Company'] || answers['insurance_company'] || hidden.insurance_company || '',
  memberId: answers['Member ID'] || answers['member_id'] || hidden.member_id || '',
  policyNumber: answers['Policy Number'] || answers['policy_number'] || '',
  groupNumber: answers['Group Number'] || answers['group_number'] || '',
  insurancePhone: answers['Insurance Phone'] || answers['insurance_phone'] || '',

  // Medical History
  currentConditions: answers['Current Medical Conditions'] || answers['current_conditions'] || '',
  pastSurgeries: answers['Past Surgeries'] || answers['past_surgeries'] || '',
  familyHistory: answers['Family Medical History'] || answers['family_history'] || '',

  // Medications
  takesMedications: answers['Do you take any medications?'] || answers['takes_medications'] || 'No',
  medications: answers['Current Medications'] || answers['medications'] || '',

  // Allergies
  hasAllergies: answers['Do you have any allergies?'] || answers['has_allergies'] || 'No',
  allergies: answers['Allergies'] || answers['allergies'] || '',

  // Emergency Contact
  emergencyContactName: answers['Emergency Contact Name'] || answers['emergency_name'] || '',
  emergencyContactRelationship: answers['Emergency Contact Relationship'] || answers['emergency_relationship'] || '',
  emergencyContactPhone: answers['Emergency Contact Phone'] || answers['emergency_phone'] || '',

  // Metadata
  submittedAt: submission.submitted_at || new Date().toISOString(),
  formId: submission.form_id || '',
  responseId: submission.response_id || ''
};

// Split full name into first/last
if (patientData.fullName) {
  const nameParts = patientData.fullName.trim().split(' ');
  patientData.firstName = nameParts[0] || '';
  patientData.lastName = nameParts.slice(1).join(' ') || nameParts[0]; // Fallback to first name if no last name
}

// Validate required fields
const errors = [];
if (!patientData.fullName) errors.push('Missing: Full Name');
if (!patientData.dateOfBirth) errors.push('Missing: Date of Birth');
if (!patientData.gender) errors.push('Missing: Gender');
if (!patientData.phone) errors.push('Missing: Phone');

return {
  json: {
    ...patientData,
    validationErrors: errors,
    isValid: errors.length === 0
  }
};

// Map Typeform data to Athenahealth FHIR Patient resource
const patient = $input.first().json;

// Convert date of birth to FHIR format (YYYY-MM-DD)
let dobFormatted = patient.dateOfBirth;
if (dobFormatted && dobFormatted.includes('/')) {
  // Convert MM/DD/YYYY to YYYY-MM-DD
  const parts = dobFormatted.split('/');
  if (parts.length === 3) {
    dobFormatted = `${parts[2]}-${parts[0].padStart(2, '0')}-${parts[1].padStart(2, '0')}`;
  }
}

// Map gender to FHIR code
const genderMap = {
  'Male': 'male',
  'Female': 'female',
  'Other': 'other',
  'Prefer not to say': 'unknown'
};
const genderCode = genderMap[patient.gender] || 'unknown';

// Build FHIR Patient resource
const fhirPatient = {
  resourceType: 'Patient',
  identifier: [
    {
      system: 'http://dr-jennifer-practice.com/patient-id',
      value: patient.appointmentId || patient.responseId
    }
  ],
  name: [
    {
      use: 'official',
      family: patient.lastName,
      given: [patient.firstName],
      text: patient.fullName
    }
  ],
  telecom: [
    {
      system: 'phone',
      value: patient.phone,
      use: 'mobile'
    },
    {
      system: 'email',
      value: patient.email,
      use: 'home'
    }
  ],
  gender: genderCode,
  birthDate: dobFormatted,
  address: [
    {
      use: 'home',
      type: 'both',
      line: [patient.streetAddress],
      city: patient.city,
      state: patient.state,
      postalCode: patient.zipCode,
      country: 'US'
    }
  ],
  contact: [
    {
      relationship: [
        {
          text: patient.emergencyContactRelationship
        }
      ],
      name: {
        text: patient.emergencyContactName
      },
      telecom: [
        {
          system: 'phone',
          value: patient.emergencyContactPhone
        }
      ]
    }
  ]
};

// Build AllergyIntolerance resources (if patient has allergies)
const allergyResources = [];
if (patient.hasAllergies === 'Yes' && patient.allergies) {
  const allergyList = patient.allergies.split(',').map(a => a.trim()).filter(a => a);
  allergyList.forEach((allergy, index) => {
    allergyResources.push({
      resourceType: 'AllergyIntolerance',
      clinicalStatus: {
        coding: [{
          system: 'http://terminology.hl7.org/CodeSystem/allergyintolerance-clinical',
          code: 'active'
        }]
      },
      code: {
        text: allergy
      },
      patient: {
        reference: 'Patient/PLACEHOLDER' // Will be updated after patient creation
      }
    });
  });
}

// Build MedicationStatement resources (if patient takes medications)
const medicationResources = [];
if (patient.takesMedications === 'Yes' && patient.medications) {
  const medList = patient.medications.split(',').map(m => m.trim()).filter(m => m);
  medList.forEach((medication, index) => {
    medicationResources.push({
      resourceType: 'MedicationStatement',
      status: 'active',
      medicationCodeableConcept: {
        text: medication
      },
      subject: {
        reference: 'Patient/PLACEHOLDER' // Will be updated after patient creation
      }
    });
  });
}

// Build Coverage resource (insurance)
const coverageResource = patient.insuranceCompany ? {
  resourceType: 'Coverage',
  status: 'active',
  type: {
    text: 'Health Insurance'
  },
  subscriber: {
    reference: 'Patient/PLACEHOLDER'
  },
  beneficiary: {
    reference: 'Patient/PLACEHOLDER'
  },
  payor: [
    {
      display: patient.insuranceCompany
    }
  ],
  class: [
    {
      type: {
        text: 'Member ID'
      },
      value: patient.memberId
    },
    {
      type: {
        text: 'Policy Number'
      },
      value: patient.policyNumber
    },
    {
      type: {
        text: 'Group Number'
      },
      value: patient.groupNumber
    }
  ]
} : null;

return {
  json: {
    originalPatientData: patient,
    fhirPatient: fhirPatient,
    fhirAllergies: allergyResources,
    fhirMedications: medicationResources,
    fhirCoverage: coverageResource,
    resourceCount: {
      patient: 1,
      allergies: allergyResources.length,
      medications: medicationResources.length,
      coverage: coverageResource ? 1 : 0
    }
  }
};

// Extract patient ID from Athenahealth response
const athenaResponse = $input.first().json;

let patientId = '';

// Response structure: { id: "12345", resourceType: "Patient", ... }
if (athenaResponse.id) {
  patientId = athenaResponse.id;
} else if (athenaResponse.entry && athenaResponse.entry[0]) {
  // Bundle response
  patientId = athenaResponse.entry[0].resource.id;
}

const originalData = $('Map to FHIR Format').first().json.originalPatientData;

return {
  json: {
    athenaPatientId: patientId,
    patientName: originalData.fullName,
    appointmentId: originalData.appointmentId,
    appointmentDate: originalData.appointmentDate,
    appointmentTime: originalData.appointmentTime,
    phone: originalData.phone,
    athenaResponse: athenaResponse
  }
};

// Log validation error
const patient = $input.first().json;

console.error('❌ Typeform submission validation failed');
console.error('Errors:', patient.validationErrors);
console.error('Patient data:', patient);

return {
  json: {
    error: 'Validation failed',
    errors: patient.validationErrors,
    patientData: patient,
    message: 'Form submission incomplete - manual review required'
  }
};
